solution:
#include <stdio.h>
#include <string.h>

int main(void) {
    char word[101];
    scanf("%100s", word);
    int len = strlen(word);
    for (int i = len - 1; i >= 0; i--) {
        printf("%c", word[i]);
    }
    printf("\n");
    return 0;
}
